  suspendMember,
  updateMemberRole,
} from "@/server/services/member-service";
import { notify } from "@/server/services/notification-service";
import { getOrganizationSummary, listOrganizationsForUser } from "@/server/services/organization-service";
import { NotFoundError } from "@/server/services/_support";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { MemberId, OrgId } from "@/types/common";
import type { TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Role } from "@/types/member";

let cleanup: () => void;
let detachAudit: Unsubscribe;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachAudit = registerActivityListeners();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  detachAudit();
  cleanup();
});

function capture(type: TaskflowEventType): unknown[] {
  const seen: unknown[] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
