      memberId: await memberIdOf(tenant, "viewer"),
    });

    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(before - 1);
  });

  it("receives no notifications, and keeps the ones it had", async () => {
    const tenant = await createTenant("susp-notify", "growth");
    const payload = { title: "t", body: "b", href: "/x", actorId: tenant.userIds.owner };

    const first = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.member], payload);
    expect(first).toHaveLength(1);

    await suspend(tenant, "admin", "member");
    const during = await notify(
      tenant.org.id,
      "issue_assigned",
      [tenant.userIds.member, tenant.userIds.viewer],
      payload,
    );
    expect(during.map((row) => row.recipientId)).toEqual([tenant.userIds.viewer]);
    await expect(notificationRepo.countUnread(tenant.org.id, tenant.userIds.member)).resolves.toBe(1);
  });

  it("is skipped by the digest until reinstated", async () => {
    const tenant = await createTenant("susp-digest", "growth");
    await notificationRepo.insertNotification(tenant.org.id, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      kind: "issue_assigned",
      title: "Unread",
      body: "b",
      href: "/x",
      actorId: null,
      channels: ["in_app"],
    });
    const windowStart = toIsoTimestamp(new Date(Date.now() - 3_600_000));
    const windowEnd = toIsoTimestamp(new Date(Date.now() + 3_600_000));

    await suspend(tenant, "admin", "member");
    await expect(
      buildDigest(tenant.org.id, tenant.userIds.member, windowStart, windowEnd),
    ).resolves.toBeNull();
    await expect(listDigestRecipients(tenant.org.id)).resolves.not.toContain(tenant.userIds.member);

    await reinstateMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      memberId: await memberIdOf(tenant, "member"),
    });
    const bundle = await buildDigest(tenant.org.id, tenant.userIds.member, windowStart, windowEnd);
    expect(bundle?.entries).toHaveLength(1);
  });

  it("cannot be handed new work, but keeps what they had", async () => {
    const tenant = await createTenant("susp-assign", "growth");
    const held = await createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Already mine", assigneeId: tenant.userIds.viewer }),
    );
    const fresh = await createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Up for grabs" }),
    );

    await suspend(tenant, "admin", "viewer");
    const created = capture("issue.created");
    const assigned = capture("issue.assigned");

    await expect(
      createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "For viewer", assigneeId: tenant.userIds.viewer }),
      ),
    ).rejects.toBeInstanceOf(MemberSuspendedError);
    await expect(
      assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: fresh.id,
        assigneeId: tenant.userIds.viewer,
      }),
    ).rejects.toMatchObject({ code: "conflict" });
    expect(created).toHaveLength(0);
    expect(assigned).toHaveLength(0);

    const unassigned = await assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: held.id,
      assigneeId: null,
    });
    expect(unassigned.assigneeId).toBeNull();
    const toActive = await assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: held.id,
      assigneeId: tenant.userIds.admin,
    });
    expect(toActive.assigneeId).toBe(tenant.userIds.admin);
  });

  it("cannot be mentioned by handle or by id", async () => {
    const tenant = await createTenant("susp-mention", "growth");
    const issue = await createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Discuss" }),
    );
    await suspend(tenant, "admin", "viewer");
    const created = capture("comment.created") as { mentionedUserIds: string[] }[];

    const comment = await createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      parentId: null,
      body: "cc @viewer and @admin",
      mentionedUserIds: [tenant.userIds.viewer, tenant.userIds.owner],
    } as never);

    expect(comment.mentionedUserIds).toEqual([tenant.userIds.admin, tenant.userIds.owner]);
    expect(created[0]?.mentionedUserIds).toEqual([tenant.userIds.admin, tenant.userIds.owner]);
  });
});

